"use strict";const videos=document.querySelectorAll(".thumbnail-video");class VideoComponent{constructor(t){this.element=t,this.video=this.element.querySelector("video:not(.fancy)"),this.muteButton=this.element.querySelector(".icon-mute"),this.playButton=this.element.querySelector(".play-icon:not(.fancy)"),this.init()}init(){this.addEventListeners()}addEventListeners(){this.muteButton&&this.muteButton.addEventListener("click",()=>this.handleMuteClick()),this.playButton&&this.playButton.addEventListener("click",t=>this.handlePlayClick(t)),this.video&&this.video.addEventListener("pause",t=>this.setButtonState(t)),this.video&&this.video.addEventListener("play",t=>this.setButtonState(t))}handleMuteClick(){this.video.muted=!this.video.muted,this.muteButton.classList.toggle("muted"),1==this.video.muted?this.video.muted=!1:this.video.muted=!0}handlePlayClick(t){this.isPlaying()?this.pause():this.play()}play(){this.video.play()}setButtonState(t){this.isPlaying()?this.playButton.classList.add("play"):this.playButton.classList.remove("play")}pause(){this.video.pause()}isPlaying(){return!this.video.paused}}videos.forEach(t=>{new VideoComponent(t)});